    Lemma fail_fin : forall s ps errv1 mo mc (r : rv) Fx j8 mw bw ew xg ng j6 fsv (q ev loc : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nst0 s ps errv1 mc -> psOK ps -> stk rsegs mc lo (bv_unsigned spw) ->
      uframe mc spw j8 mw bw ew xg ng j6 fsv s3 s2 s1 s0 ra ->
      bregs r -> ra0 r = a0 -> ra1 r = Z_to_bv 64 q -> ra2 r = Z_to_bv 64 ev -> ra3 r = Z_to_bv 64 loc ->
      p <= q <= e -> 1 <= ev < 1000 -> 2 <= loc < 2^32 ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x5fc14) fc None mc (seg_rom rsegs)) mo).
Proof.
