    Lemma ufi_fin : forall s ps errv1 mo mc (r : rv) Fx fcx j8 mw bw ew xg ng j6 fsv (p' : Z) (pbk : bptr) (Bb cap : Z) (items : list vsitem),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nst0 s ps errv1 mc -> psOK ps -> stk rsegs mc lo (bv_unsigned spw) -> frm0 fcx ->
      uframe mc spw j8 mw bw ew xg ng j6 fsv s3 s2 s1 s0 ra ->
      ps_vs ps = mkVS (Some (pbk, Bb, 24 * cap)) cap items 0 (pa + 280) -> Z.of_nat (length items) < cap ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> ra0 r = Z_to_bv 64 (Bb + 24 * Z.of_nat (length items)) -> p < p' <= e ->
