    Lemma fini_fin : forall s ps errv1 mo mc (r : rv) Fx j8 mw bw ew xg ng j6 fsv (p' : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) ->
