    Lemma xlh_loop : forall (q : Z) s ps errv1 mo mc (r : rv) Fx j8 mw mcw (bias expo xn : Z) j6 fsv,
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      uframe mc spw j8 mcw (Z_to_bv 64 bias) (Z_to_bv 64 expo) (b8 xn) (b8 0) j6 fsv s3 s2 s1 s0 ra ->
      0 <= expo < 2^31 -> -2^31 < bias <= 0 -> 0 <= xn <= 1 ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 q -> ra3 r = Z_to_bv 64 expo -> ra0 r = mw -> ra2 r = Z_to_bv 64 bias ->
      ra4 r = Z_to_bv 64 9 -> ra5 r = Z_to_bv 64 2 -> ra6 r = Z_to_bv 64 56 -> ra7 r = Z_to_bv 64 (-2147483649) ->
      rt0 r = Z_to_bv 64 214748364 -> rt1 r = Z_to_bv 64 10 ->
      p < q < e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x5fc90) fc None mc (seg_rom rsegs)) mo).
Proof.
