    (* [comment removed for export] *)
    (* [comment removed for export] *)
    Lemma frh_loopn : forall (n : nat) (q : Z) s ps errv1 mo mc (r : rv) Fx j8 mw (bias : Z) j6 fsv,
      (Z.to_nat (e - q) <= n)%nat ->
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      uframe mc spw j8 mw (Z_to_bv 64 bias) (Z_to_bv 64 0) (b8 0) (b8 0) j6 fsv s3 s2 s1 s0 ra ->
      -2^31 < bias <= 0 ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 q -> ra0 r = mw -> ra2 r = Z_to_bv 64 bias ->
      ra3 r = Z_to_bv 64 9 -> ra4 r = Z_to_bv 64 1 -> ra5 r = Z_to_bv 64 (-2147483648) -> ra6 r = Z_to_bv 64 10 ->
      p < q < e ->
