    (* [comment removed for export] *)
    Lemma apu_fin : forall s ps errv1 mo mc (r : rv) Fx j8 j6 fsv mw (q nd : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      uframe mc spw j8 (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 fsv s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> rs2 r = Z_to_bv 64 nd -> ra0 r = mw -> p + 1 < q -> q + 31 <= e -> 1 <= nd <= 16 ->
